mapper.select:
select bm_weigh_ticket.id, bm_weigh_ticket.ticket_no, bm_weigh_ticket.material_name, bm_weigh_ticket.material_merge_code, bm_storage_material_batch.material_batch_no as storage_material_batch_no, bm_storage_material_batch.id as storage_material_batch_id, bm_weigh_ticket.material_specification, bm_weigh_centre.id as weigh_centre_id, bm_weigh_centre.name as weigh_centre_name, bm_weigh_ticket.requirement_quantity, bm_weigh_ticket.unit_id, bm_weigh_ticket.plan_date, bm_weigh_ticket.status from bm_weigh_ticket left join bm_storage_material_batch on bm_weigh_ticket.storage_material_batch_id = bm_storage_material_batch.id and bm_storage_material_batch.is_deleted = 0 left join bm_weigh_centre on bm_weigh_ticket.weigh_centre_id = bm_weigh_centre.id and bm_weigh_centre.is_deleted = 0 where bm_weigh_ticket.is_deleted = 0 and bm_weigh_ticket.status != 3 and bm_weigh_ticket.weigh_centre_id in
#{centreId}
and bm_weigh_ticket.ticket_no like concat('%', #{page.ticketNo}, '%')
and bm_weigh_ticket.material_name like concat('%', #{page.materialName}, '%')
and bm_weigh_ticket.material_merge_code like concat('%', #{page.materialMergeCode}, '%')
and bm_weigh_centre.name like concat('%', #{page.weighCentreName}, '%')
and DATE_FORMAT(bm_weigh_ticket.plan_date, '%Y-%m-%d') >= #{page.planDateStart}
and DATE_FORMAT(bm_weigh_ticket.plan_date, '%Y-%m-%d') <= #{page.planDateEnd}
order by bm_weigh_ticket.create_time desc
